/**
 * @template [T = KVValue]
 * @overload
 * @param {string} key
 * @param {KVIncrementPath} pathAndAmount
 * @param {KVOptConfig} [optConfig]
 * @returns {Promise<T>}
 */
export function incr<T = unknown>(key: string, pathAndAmount: KVIncrementPath, optConfig?: import("./types.js").KVOptConfig | undefined): Promise<T>;
/**
 * @overload
 * @param {string} key
 * @param {KVOptConfig} optConfig
 * @returns {Promise<number>}
 */
export function incr(key: string, optConfig: KVOptConfig): Promise<number>;
/**
 * @overload
 * @param {string} key
 * @param {number} [amount]
 * @param {KVOptConfig} [optConfig]
 * @returns {Promise<number>}
 */
export function incr(key: string, amount?: number | undefined, optConfig?: import("./types.js").KVOptConfig | undefined): Promise<number>;
export type KVIncrementPath = import("./types.js").KVIncrementPath;
export type KVOptConfig = import("./types.js").KVOptConfig;
export type KVValue = import("./types.js").KVValue;
